// src/checks/lyrie/ly-005-stale-pending-pairings.ts
init_check_builder();
import { join as join86 } from "path";
var STALE_DAYS = 7;
var ly005 = defineCheck({
  id: "LY-005",
  name: "Stale Pending DM Pairings",
  category: "lyrie",
  severity: "warning",
  description: "Detect pending DM-pairing requests in ~/.lyrie/pairing.json older than 7 days \u2014 pairing codes never expire in Lyrie 3.4.0, so abandoned requests stay approvable indefinitely and obscure new ones.",
  supportedAgents: ["lyrie"],
  async run(ctx, h) {
    const path = join86(lyrieStateDir(ctx.fs), "pairing.json");
    if (!await ctx.fs.access(path)) return h.passed("pairing.json not present");
    const evidence = [];
    try {
      const data = JSON.parse(await ctx.fs.readFile(path));
      const pending = Array.isArray(data?.pending) ? data.pending : [];
      const cutoff = Date.now() - STALE_DAYS * 24 * 60 * 60 * 1e3;
      const stale = pending.filter((p) => {
        if (!p || typeof p !== "object") return false;
        const requestedAt = p.requestedAt;
        if (typeof requestedAt !== "string") return false;
        const ts = Date.parse(requestedAt);
        return Number.isFinite(ts) && ts < cutoff;
      });
      if (stale.length > 0) {
        evidence.push({
          file: path,
          detail: `${stale.length} pending pairing request(s) older than ${STALE_DAYS} days \u2014 their codes are still approvable`
        });
      }
    } catch {
    }
    return h.fromEvidence(evidence, {
      passed: "No stale pending pairings",
      failed: () => "Stale pending pairings detected",
      fixDescription: "In the Lyrie checkout run `bun run pairing list`, then approve legitimate senders (`bun run pairing approve <channel> <code>`) and remove the rest from ~/.lyrie/pairing.json"
    });
  }
});

