      const requireLocal = envTrue(config, "LYRIE_REQUIRE_LOCAL");
      if (!localMode && !requireLocal) continue;
      const keys = CLOUD_PROVIDER_KEYS.filter((k) => isConfigured(envString(config, k)));
      if (keys.length === 0) continue;
