// src/checks/lyrie/ly-012-stale-edit-approvals.ts
init_check_builder();
import { join as join87 } from "path";
var STALE_HOURS = 24;
var ly012 = defineCheck({
  id: "LY-012",
  name: "Stale Pending Edit Approvals",
  category: "lyrie",
  severity: "warning",
  description: "Detect pending diff-view edit plans in ~/.lyrie/edits.json older than 24 hours \u2014 a long approval queue signals operator inattention, and old plans approved later apply against file state that has drifted since they were reviewed.",
  supportedAgents: ["lyrie"],
  async run(ctx, h) {
    const path = join87(lyrieStateDir(ctx.fs), "edits.json");
    if (!await ctx.fs.access(path)) return h.passed("edits.json not present");
    const evidence = [];
    try {
      const data = JSON.parse(await ctx.fs.readFile(path));
      const pending = Array.isArray(data?.pending) ? data.pending : [];
      const cutoff = Date.now() - STALE_HOURS * 60 * 60 * 1e3;
      const stale = pending.filter((p) => {
        if (!p || typeof p !== "object") return false;
        const createdAt = p.createdAt;
        if (typeof createdAt !== "string") return false;
        const ts = Date.parse(createdAt);
        return Number.isFinite(ts) && ts < cutoff;
      });
      if (stale.length > 0) {
        evidence.push({
          file: path,
          detail: `${stale.length} pending edit plan(s) older than ${STALE_HOURS} hours \u2014 re-review before approving`
        });
      }
    } catch {
    }
    return h.fromEvidence(evidence, {
      passed: "No stale pending edit approvals",
      failed: () => "Stale pending edit approvals detected",
      fixDescription: "In the Lyrie checkout run `bun run edits list` and `bun run edits review <planId>`, then approve (`bun run edits approve <planId>`) or discard each plan"
    });
  }
});

